style.css:
@-moz-document domain("youtube.com") {
:root {
  --my-bg: #06140c;
  --my-surface: #0b2113;
  --my-green: #00c878;
  --my-gold: #e5bd45;
  --my-text: #f1f5e9;
}

/* Money-inspired background */
html,
body,
ytd-app,
#content,
ytd-browse,
ytd-watch-flexy {
  background-color: var(--my-bg) !important;
  background-image:
    radial-gradient(ellipse at 15% 20%, #124b2866, transparent 45%),
    radial-gradient(ellipse at 85% 80%, #b38a1730, transparent 40%) !important;
  color: var(--my-text) !important;
}

/* Dollar pattern */
ytd-app::before {
  content: "$  $  $  $  $  $  $";
  position: fixed !important;
  inset: 15% -10% auto -10% !important;
  height: 100vh !important;
  pointer-events: none !important;
  z-index: 0 !important;
  color: #d4af3710 !important;
  font-size: 100px !important;
  font-weight: 900 !important;
  line-height: 2.2 !important;
}

/* Header */
ytd-masthead {
  background: #06140cf5 !important;
  border-bottom: 1px solid #d4af3740 !important;
}

/* Sidebar */
#guide,
ytd-mini-guide-renderer {
  background: #07190e !important;
}

/* Video cards */
ytd-rich-item-renderer,
ytd-video-renderer,
ytd-compact-video-renderer {
  border-radius: 16px !important;
}

/* Thumbnails */
ytd-rich-item-renderer img,
ytd-video-renderer img {
  border-radius: 14px !important;
  border: 1px solid #d4af3725 !important;
}

/* Search */
#center #container {
  background: #102b19 !important;
  border: 1px solid #d4af3760 !important;
  border-radius: 30px !important;
}

#search-icon-legacy {
  background: linear-gradient(135deg, #08783e, #d4af37) !important;
}

/* Buttons */
ytd-subscribe-button-renderer button {
  background: linear-gradient(120deg, #087b40, #13c477) !important;
  color: white !important;
  border-radius: 25px !important;
}

/* Category chips */
yt-chip-cloud-chip-renderer {
  background: #102b19 !important;
  border: 1px solid #d4af3735 !important;
  border-radius: 25px !important;
}

/* Text */
#video-title,
.title,
yt-formatted-string {
  color: var(--my-text) !important;
}

/* Comments */
ytd-comment-thread-renderer {
  background: #0d2415 !important;
  border-radius: 14px !important;
}

/* Gold hover */
a:hover {
  color: var(--my-gold) !important;
}

/* Scrollbar */
::-webkit-scrollbar-thumb {
  background: linear-gradient(#087b40, #d4af37) !important;
  border-radius: 10px !important;
}
}
